import heapq

def match(orders):
    trades = []
    buy_heap = []   # entries: (-price, time, id)
    sell_heap = []  # entries: (price, time, id)
    order_info = {}  # id -> dict(side, price, qty, time)

    def get_top(heap):
        while heap:
            entry = heap[0]
            oid = entry[2]
            if oid not in order_info:
                heapq.heappop(heap)
                continue
            return entry
        return None

    for t, order in enumerate(orders):
        op = order[0]

        if op == 'cancel':
            oid = order[1]
            if oid in order_info:
                del order_info[oid]
            continue

        if op == 'limit':
            _, oid, side, price, qty = order
        elif op == 'ioc':
            _, oid, side, price, qty = order
        elif op == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            opposite = sell_heap
            while remaining > 0:
                top = get_top(opposite)
                if top is None:
                    break
                r_price, r_time, r_id = top
                if op != 'market' and r_price > price:
                    break
                heapq.heappop(opposite)
                r_info = order_info[r_id]
                r_qty = r_info['qty']
                trade_qty = min(remaining, r_qty)
                trades.append([oid, r_id, r_price, trade_qty])
                remaining -= trade_qty
                r_qty -= trade_qty
                if r_qty > 0:
                    r_info['qty'] = r_qty
                    heapq.heappush(opposite, (r_price, r_time, r_id))
                else:
                    del order_info[r_id]

            if op == 'limit' and remaining > 0:
                order_info[oid] = {'side': side, 'price': price, 'qty': remaining, 'time': t}
                heapq.heappush(buy_heap, (-price, t, oid))

        else:  # sell
            opposite = buy_heap
            while remaining > 0:
                top = get_top(opposite)
                if top is None:
                    break
                neg_price, r_time, r_id = top
                r_price = -neg_price
                if op != 'market' and r_price < price:
                    break
                heapq.heappop(opposite)
                r_info = order_info[r_id]
                r_qty = r_info['qty']
                trade_qty = min(remaining, r_qty)
                trades.append([r_id, oid, r_price, trade_qty])
                remaining -= trade_qty
                r_qty -= trade_qty
                if r_qty > 0:
                    r_info['qty'] = r_qty
                    heapq.heappush(opposite, (neg_price, r_time, r_id))
                else:
                    del order_info[r_id]

            if op == 'limit' and remaining > 0:
                order_info[oid] = {'side': side, 'price': price, 'qty': remaining, 'time': t}
                heapq.heappush(sell_heap, (price, t, oid))

    return trades

